// WF-5: email a Westrom Group owner-portal sign-in code.
// Called only by the wgcassetguide.com API (/api/portal/login/start), which
// decides who may get a code. The webhook node requires the "WGC gateway"
// Header Auth credential (X-WGC-Gateway), the same one WF-0 and WF-1 use.
// Sends nothing unless the payload is exactly { email, code(6 digits), name?, minutes }.
const crypto = require('crypto');
const body = $json.body || {};
const headers = $json.headers || {};
const GW = $env.WGC_GATEWAY_SECRET || '';
if (GW) {
  const got = Buffer.from(String(headers['x-wgc-gateway'] || ''), 'utf8');
  const exp = Buffer.from(GW, 'utf8');
  if (got.length !== exp.length || !crypto.timingSafeEqual(got, exp)) return [{ json: { reject: true } }];
}
const email = String(body.email || '').trim().toLowerCase();
const code = String(body.code || '');
const minutes = Math.min(30, Math.max(1, Number(body.minutes) || 10));
const name = String(body.name || '').replace(/[<>&"]/g, '').trim().slice(0, 80);
if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email) || email.length > 254 || !/^\d{6}$/.test(code)) return [{ json: { reject: true } }];
const first = name ? name.split(' ')[0] : '';
const spaced = code.slice(0, 3) + ' ' + code.slice(3);
const html = '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Your sign-in code</title></head>' +
  '<body style="margin:0;padding:0;background:#f2efe7;font-family:Helvetica,Arial,sans-serif;color:#16171a">' +
  '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f2efe7"><tr><td align="center" style="padding:40px 16px">' +
  '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:520px;background:#ffffff;border:1px solid #e3ddd0">' +
  '<tr><td style="padding:32px 32px 8px;font-size:12px;letter-spacing:3px;text-transform:uppercase;color:#85827a">Westrom Group · Owner portfolio</td></tr>' +
  '<tr><td style="padding:8px 32px 0;font-family:Georgia,serif;font-size:28px;line-height:1.2">' + (first ? 'Hello ' + first + ',' : 'Hello,') + '</td></tr>' +
  '<tr><td style="padding:16px 32px 0;font-size:16px;line-height:1.6;color:#4b4c50">Here is your code to sign in to your owner portfolio. It works for ' + minutes + ' minutes.</td></tr>' +
  '<tr><td style="padding:24px 32px"><div style="font-family:Georgia,serif;font-size:44px;letter-spacing:10px;color:#a8170f">' + spaced + '</div></td></tr>' +
  '<tr><td style="padding:0 32px 32px;font-size:14px;line-height:1.6;color:#85827a">If you did not ask for this code, you can ignore this email; nobody can sign in without it. Questions: (817) 445-1108.</td></tr>' +
  '</table></td></tr></table></body></html>';
const text = (first ? 'Hello ' + first + ',' : 'Hello,') + '\n\nYour Westrom Group owner portfolio sign-in code is ' + spaced + '.\nIt works for ' + minutes + ' minutes.\n\nIf you did not ask for this code, you can ignore this email.\nWestrom Group, (817) 445-1108';
return [{ json: { reject: false, email, name, subject: 'Your Westrom Group sign-in code: ' + spaced, html, text } }];
